window.DAILY = {"generated_utc": "2026-11-24T23:04:47Z", "date_cn": "2026-11-25", "window_days": 3, "source": "arXiv OAI-PMH/API (cs.CV/cs.RO) · 热度加成: Hugging Face Daily Papers", "note": "所有条目直接来自 arXiv 元数据，未经人工或模型改写；预印本未经同行评审。", "tracks": {"slam": {"name": "SLAM 与状态估计", "papers": [{"id": "2611.22235", "title": "CoSphere-SLAM: Multi-Agent Panoramic Gaussian Splatting SLAM with Spherical Loop Closure", "authors": ["Qi Shao", "Zhihao Cao", "Shuhao Zhai", "Taoyu Wu", "Zhuoxiao Li", "Anh Nguyen", "Long Hu", "Xianzhi Li", "Hong Liang", "Liang Li", "Baoru Huang"], "abstract": "Dense collaborative mapping is essential for search and rescue, building inspection, and warehouse automation, where panoramic cameras capture the entire surroundings in a single frame. Unlike pinhole agents that share views only at similar headings, panoramic agents observe overlapping scenes at any 3D orientation, yet searching full rotations also produces mutually consistent false loop closures across distinct symmetric rooms. Moreover, continuous monocular scale drift splits rigidly merged maps at revisited surfaces, while depth noise at short baselines distorts loop translation directions. To address these challenges, we propose CoSphere-SLAM, the first multi-agent Gaussian splatting SLAM framework for panoramic cameras, whose spherical loop closure aligns spherical features over $\\mathrm{SO}(3)$ via fast Fourier correlation across arbitrary orientations and rejects symmetric false closures through global $\\mathrm{Sim}(3)$ consensus. Building on these closures, directional global optimization solves a per-keyframe $\\mathrm{Sim}(3)$ pose graph with log-scale regularization to correct scale drift while separating optical-flow translation directions from depth-based magnitudes. Finally, omnidirectional Gaussian fusion transforms each Gaussian with its keyframe similarity and renders Gaussians at their maximum ray response to jointly refine poses and maps. Experiments on indoor and cross-session multi-agent panoramic benchmarks demonstrate that CoSphere-SLAM achieves state-of-the-art trajectory accuracy and rendering quality among single-agent and multi-agent methods. Project website: https://cosphere-slam.github.io.", "published": "2026-11-22", "comment": "9 pages, 4 figures, 7 tables. Project website: https://cosphere-slam.github.io", "url": "https://arxiv.org/abs/2611.22235"}, {"id": "2602.07493", "title": "TOM-GS: Robust Thermal Odometry and Mapping with Depth-Guided Gaussian Splatting", "authors": ["Tianhao Zhou", "Shengqian Wang", "Zhihao Zhan", "Yuhang Ming", "Jianzhu Huai"], "abstract": "Thermal infrared cameras offer robustness to darkness, smoke, and illumination changes, making them attractive for robotic deployment in visually degraded environments. However, most existing thermal SLAM systems are geometric and produce sparse maps, while recent learning-based odometry and neural mapping methods are primarily developed for RGB imagery. We present TOM-GS, a monocular thermal odometry and mapping system that integrates learning-based dense tracking with depth-guided 3D Gaussian Splatting for dense reconstruction. Monocular depth priors are used to stabilize thermal odometry and supervise Gaussian geometry, improving scale consistency and robustness in low-texture scenes. Experiments on the RRXIO and VIVID benchmarks show that learned thermal odometry outperforms classical geometric pipelines and that thermal sensing provides improved robustness over RGB under degraded illumination. Furthermore, Gaussian Splatting enables high-quality dense thermal reconstruction in challenging environments.", "published": "2026-11-23", "comment": "9 pages, 4 figures, 3 tables, IROS 2026 Pittsburgh", "url": "https://arxiv.org/abs/2602.07493"}, {"id": "2611.30166", "title": "Toward Open Room-Scale Scanning with Consumer LiDAR via Depth-Inertial Odometry", "authors": ["Minsuk Jang"], "abstract": "Room scanning with consumer LiDAR today depends on ARKit, whose tracking and map update are a black box: an application receives depth and poses but cannot inspect how they were produced, so an error in a scan cannot be traced to its cause. This paper examines whether an open alternative, one whose every stage can be inspected, is feasible on the device. Mobile-LIO is a depth-inertial odometry pipeline that uses the phone's depth and inertial data and no ARKit poses. On seven ScanNet++ iPhone recordings it completed every scene with 0.2-2.0 m deviation from the ARKit-derived reference, where six open-source LiDAR-inertial estimators run as configured for dedicated scanners had at least 4.46 m in 41 of 42 runs (two of the six also failed a noise-free adapter check, and Mobile-LIO has a speed cap they lack; the comparison is not controlled and does not rone 15 Pro Max, a buildwith corrected phone code kept up with the sensor in 14 of 15 replay runs of three 7-13 s recordings; e estimator before thosecorrections. Laser-scanned meshes give the accuracy. Within 3 m, recorded depth differed from the m on three held-out scenes,maps fused with ARKit poses that the dataset scales and aligns to the mesh la a median 1.8-2.3 cm from 17 cm. Because thepipeline is open, the gap could be examined: in the scene with the largest error, noise-free renderefrom 1.97 m to 0.04 m, sorecorded depth, whose error reached 20-54 cm at 5-7 m, contributed alongside the estimator. An open de tracked on phone depth and kept up with the sensor in short phone replays, but it is not yet as accurate as ARKit-pose maps, whicheach only the coarsestUSIBD accuracy level (LOA10); its accuracy on the device was not measured.", "published": "2026-11-23", "comment": null, "url": "https://arxiv.org/abs/2611.30166"}, {"id": "2609.36217", "title": "Sparse-View Interpretable 3D Animal Behavior Representations for Neural Encoding and Decoding", "authors": ["Xinming Dai", "Qihang Jin", "Tianshu Tan", "Baiyuan Chen", "Hanrui Lyu", "Lenny Aharon", "Kyle Daruwalla", "Xun Helen Hou", "Matthew R. Whiteway", "Liam Paninski", "Yizi Zhang"], "abstract": "A deeper understanding of brain function requires a precise, structured characterization of behavior. Yet, extracting behavioral representations from video in a form suitable for scientific analysis remains a fundamental challenge. Many prior studies represent behavior via pose estimation or nonlinear video embeddings. However, pose tracking discards rich information beyond predefined keypoints, while nonlinear video embeddings lack interpretability. We address this limitation with SABLE (Sparse-view Animal Behavior Latent Embeddings), a self-supervised framework that leverages a geometric inductive bias to learn behavior representations. By augmenting a multi-view transformer with priors from monocular depth and pose estimation, SABLE reconstructs 3D animal behavior from extremely sparse views while learning explicit 3D latent structure. Without ground-truth 3D labels, it reliably recovers 3D behavior from two-view videos, whereas state-of-the-art (SOTA) methods fail or yield degenerate solutions. Across the International Brain Lab and Cheese3D datasets, we demonstrate that SABLE learns 3D representations that match or exceed prior SOTA performance in neural encoding and decoding. Single-neuron analyses further identify neurons with putative 3D tuning, generating testable hypotheses about how the brain represents 3D behavior. Once pretrained across animals, SABLE serves as an off-the-shelf model that generalizes zero-shot to unseen animals without animal-specific calibration or retraining. Our method establishes 3D-aware video embeddings that capture complex behavior, opening new avenues for studying brain-behavior relationships.", "published": "2026-11-22", "comment": null, "url": "https://arxiv.org/abs/2609.36217"}, {"id": "2611.29792", "title": "A Cascaded Framework with a Cross-Attention-Guided Mamba-CNN Model for Pre- and Post-Treatment Glioma Segmentation", "authors": ["Siavash Taremi", "Mahmoud Heidari", "Seyed Mohammad Hossein Hashemi", "Mohsen Hooshmand"], "abstract": "Accurate glioma segmentation is vital for diagnosis and follow-up, but manual segmentation is time-consuming, subjective, and variable across interpreters. Gliomas are heterogeneous in size, shape, and location. Deep learning has therefore emerged as a potential solution. CNNs excel at local features but may struggle with long-range dependencies, whereas Vision Transformers capture global context efficiently but incur higher computational complexity. Most previous studies focused on pre-treatment gliomas; post-treatment cases with resection cavities (RCs) remain less explored. This study proposes a Cross-Attention-Guided Mamba-CNN (CMC-Seg) model within a cascaded framework for pre- and post-treatment diffuse glioma segmentation, aiming to balance accuracy and computational cost. Experiments used BraTS 2025 mpMRI of diffuse glioma patients. After preprocessing, a coarse segmentation model extracted tumor-centered patches, which were fed to CMC-Seg for fine-grained segmentation. CMC-Seg was compared with 3D U-Net, SegResNet, SwinUNETR, UNETR, nnFormer, and SegMamba. On the test set, CMC-Seg achieved the highest mean Dice (81.20%) and non-enhancing tumor core (NETC) Dice (77.09%). It also achieved an RC Dice of 78.63% and the lowest 95% Hausdorff distance (HD95; 4.39 mm). Results were comparable to CNN and Mamba baselines and significantly better than Transformer-based baselines (P < 0.05). CMC-Seg required the fewest inference GFLOPs (381.49). Ablation experiments indicated that multi-direction scanning and cross-attention improved performance, particularly for RC (P < 0.05). Grad-CAM explainability experiments showed that CMC-Seg focuses on diagnostically relevant tumor regions.", "published": "2026-11-22", "comment": null, "url": "https://arxiv.org/abs/2611.29792"}, {"id": "2611.29993", "title": "One Size Doesn't Fit All: Input Adaptive Class Activation Mapping for Improved Visual Explanations", "authors": ["Ayesha Sahar", "Tahir Mustafa Madni", "Tehseen Zia", "David Windridge", "Uzair Iqbal Janjua", "Waleed Umar"], "abstract": "Despite their widespread use in tasks such as image classification, object detection and semantic segmentation, the limited interpretability of Convolutional Neural Networks (CNNs) and Vision Transformers (ViTs) can undermine trust and hinder adoption in safety-critical applications. Explainable artificial intelligence (XAI) methods seek to address this by providing human-understandable explanations for model predictions. Class Activation Maps (CAM) constitute one such widely used XAI technique for visualizing discriminative regions. However, existing CAM methods may exhibit limitations in channel weighting, localization, and adaptability across network architectures potentially resulting in noisy or imprecise explanations. To address these issues, we propose ADAPT-CAM, a gradient-based, parameter-adaptive CAM framework. The method combines first-order gradient energy with activation-weighted second-order curvature to derive channel contributions. It further incorporates adaptive local contrast normalization and knee-guided soft channel selection to refine the resulting explanations. Importantly, key parameters are estimated independently for each input, allowing the framework to adapt to variations in feature representations across network architectures. We validate ADAPT-CAM on ImageNet and Oxford 102 Flowers across CNN and ViT architectures. Quantitative results demonstrate competitive or superior performance against established CAM methods across multiple evaluation metrics. In parallel, qualitative comparisons illustrate its ability to highlight discriminative image regions. Further parameter analysis and ablation experiments examine the behaviour and contributions of the individual adaptive components. These findings demonstrate the applicability of ADAPT-CAM across different architectures and datasets.", "published": "2026-11-23", "comment": "20 pages, 5 figures, 5 Tables", "url": "https://arxiv.org/abs/2611.29993"}, {"id": "2611.30173", "title": "Confidently Lost: Silent Failure and Edge Deployment of Dense Visual SLAM under Photon Starvation", "authors": ["Shrikrishna Bhagirath Rajule", "Srinath Neelamagam", "Aniket Bera"], "abstract": "Dense visual SLAM built on learned two-view geometry is evaluated in good light; in low light it fails silently. Two frames of 9-level quantized noise, no scene at all, give MASt3R-SLAM's network a cross-view geometric self-consistency of 0.936; a real dark frame pair gives 0.935. Starved of structure, the network invents the same geometry for both views and the system trusts the agreement: on a dark sequence it consumes 1,605 frames, emits 7 keyframes, rejects no factor-graph edges and reports full frame rate, while over 95% of the correspondences it accepts violate the ground-truth epipolar geometry. One inflated statistic is read by two subsystems against thresholds in opposite directions, so keyframing starves while relocalization accepts almost every candidate. The same statistic, read at keyframe-pair baselines, separates the confident collapse from working runs on the ETH3D dark sequences without ground truth or extra computation (in-sample). Low-light-adapted weights take tracked trajectories from 1/6 to 5/6, as does retuning two thresholds; neither yields accurate ones, because the adaptation withdraws confidence from wrong geometry rather than finding right geometry. Replayed on a Jetson AGX Orin carried by a legged robot, the mechanism's signature reproduces on the two darkest of four routes, and which of its faces appears varies with route geometry and sensor encoding. The network does not lose confidence in the dark; it manufactures it.", "published": "2026-11-23", "comment": "8 pages, 7 figures. Submitted to IEEE ICRA 2027", "url": "https://arxiv.org/abs/2611.30173"}, {"id": "2611.30184", "title": "OmniSLAM: Evidence-Authorized Revision of Persistent Object Maps", "authors": ["Haoxiang Jie", "Yaoyuan Yan", "Zhiyou Heng", "Liang Li", "Zhaosong Li", "Lifeng Liu"], "abstract": "Persistent object maps must incorporate new surfaces while retaining valid identities and correcting earlier associations. We present a map-revision module that separates historical identity changes from new-surface admission. Proposed merges are tested against shared and separate mask explanations across views; a merge is allowed only if its evidence margin remains positive after removing any one observed frame. New measured points are assigned through local identity competition, with a mask witness and a seed-frame stability check. On two preselected KITTI-360 windows, the fixed method increases mean building/car instance AP50:90 from 17.259 to 18.762 under a local evaluation protocol. Controlled output interventions attribute the gains to fragment consolidation, protection against harmful overwrites, and local assignment of new points. Four additional spatial holdouts increase mean AP from 20.263 to 23.171, although unconditional revision is slightly higher at 23.251. The extra seed-frame check yields no AP gain over nearest-seed assignment in either set. A 330-frame garage recording demonstrates offline integration with LiDAR--inertial--visual odometry. These results identify where observation-supported revision improves object maps and where conservative decisions still limit recovery.", "published": "2026-11-23", "comment": null, "url": "https://arxiv.org/abs/2611.30184"}, {"id": "2611.30741", "title": "Place-Revisit Consistency Evaluation of Reference Poses", "authors": ["Jianzhu Huai", "Yujia Zhang", "Grzegorz Jozkow"], "abstract": "Reference trajectories are widely used to evaluate odometry and simultaneous localization and mapping systems. However, local inconsistencies in benchmark reference poses can bias such evaluations. This paper presents a place-revisit consistency evaluation method for reference poses in mobile sensing datasets. When a platform revisits a previously observed place after a sufficient temporal gap, the relative pose implied by the reference trajectory should agree with relative poses estimated directly from onboard sensors. We instantiate this idea with lidar scan registration and stereo-image pose estimation, and apply it to the KITTI Odometry and SNAIL Radar. The KITTI analysis identifies several revisit regions where the public reference poses disagree with sensor-derived relative poses, with median translation discrepancies up to 6.60 m. Representative point-cloud overlays further localize these discrepancies and support the use of place revisits as a benchmark-validation tool.", "published": "2026-11-23", "comment": "10 pages, 4 figures, 1 table, LBS 2026 Nanjing China", "url": "https://arxiv.org/abs/2611.30741"}, {"id": "2003.04030", "title": "Learning Delicate Local Representations for Multi-Person Pose Estimation", "authors": ["Yuanhao Cai", "Zhicheng Wang", "Zhengxiong Luo", "Binyi Yin", "Angang Du", "Haoqian Wang", "Xiangyu Zhang", "Xinyu Zhou", "Erjin Zhou", "Jian Sun"], "abstract": "In this paper, we propose a novel method called Residual Steps Network (RSN). RSN aggregates features with the same spatial size (Intra-level features) efficiently to obtain delicate local representations, which retain rich low-level spatial information and result in precise keypoint localization. Additionally, we observe the output features contribute differently to final performance. To tackle this problem, we propose an efficient attention mechanism - Pose Refine Machine (PRM) to make a trade-off between local and global representations in output features and further refine the keypoint locations. Our approach won the 1st place of COCO Keypoint Challenge 2019 and achieves state-of-the-art results on both COCO and MPII benchmarks, without using extra training data and pretrained model. Our single model achieves 78.6 on COCO test-dev, 93.0 on MPII test dataset. Ensembled models achieve 79.2 on COCO test-dev, 77.1 on COCO test-challenge dataset. Code and model are publicly available for further research at https://github.com/caiyuanhao1998/RSN/ . Our project page at https://caiyuanhao1998.github.io/RSN-Project/ shows more video results. An online Gradio demo is available on HuggingFace at https://huggingface.co/spaces/CaiYuanhao/RSN", "published": "2026-11-21", "comment": "ECCV2020 Spotlight", "url": "https://arxiv.org/abs/2003.04030"}, {"id": "2507.04503", "title": "U-ViLAR: Uncertainty-Aware Visual Localization for Autonomous Driving via Differentiable Association and Registration", "authors": ["Xiaofan Li", "Zhihao Xu", "Chenming Wu", "Zhao Yang", "Yumeng Zhang", "Jiang-Jiang Liu", "Haibao Yu", "Fan Duan", "Xiaoqing Ye", "Yuan Wang", "Shirui Li", "Xun Sun", "Ji Wan", "Jun Wang"], "abstract": "Accurate localization using visual information is a critical yet challenging task, especially in urban environments where nearby buildings and construction sites significantly degrade GNSS (Global Navigation Satellite System) signal quality. This issue underscores the importance of visual localization techniques in scenarios where GNSS signals are unreliable. This paper proposes U-ViLAR, a novel uncertainty-aware visual localization framework designed to address these challenges while enabling adaptive localization using high-definition (HD) maps or navigation maps. Specifically, our method first extracts features from the input visual data and maps them into Bird's-Eye-View (BEV) space to enhance spatial consistency with the map input. Subsequently, we introduce: a) Perceptual Uncertainty-guided Association, which mitigates errors caused by perception uncertainty, and b) Localization Uncertainty-guided Registration, which reduces errors introduced by localization uncertainty. By effectively balancing the coarse-grained large-scale localization capability of association with the fine-grained precise localization capability of registration, our approach achieves robust and accurate localization. Experimental results demonstrate that our method achieves state-of-the-art performance across multiple localization tasks. Furthermore, our model has undergone rigorous testing on large-scale autonomous driving fleets and has demonstrated stable performance in various challenging urban scenarios.", "published": "2026-11-21", "comment": "Vision Localization, Autonomous Driving, Bird's-Eye-View", "url": "https://arxiv.org/abs/2507.04503"}, {"id": "2605.27101", "title": "Pop-Up Distractions Reveal Bag-of-Events Behavior in Video Large Language Models", "authors": ["Oscar Chew", "Serhii Honcharenko", "Qian-Hui Chen", "Patricia Lu", "Dishant Zaveri", "Khoa D. Doan", "Kuan-Hao Huang"], "abstract": "A key capability for video understanding is reliably linking subjects to events across time, yet whether Video Large Language Models (VideoLLMs) actually achieve this remains unclear. In this work, we introduce DistractionBench to evaluate whether VideoLLMs can robustly link subjects and events in the presence of unrelated video segments. Through controlled interventions, such as inserting short advertisement clips into longer videos, we show that VideoLLMs frequently hallucinate interactions between entities from different segments, incorrectly attributing actions from injected advertisements to subjects in the main video. We characterize this systematic hallucination as bag-of-events (BoE) behavior, where models process videos as collections of events rather than temporally structured sequences. Evaluating 11 popular VideoLLMs, we find that all models exhibit substantial BoE behavior. Our findings suggest that VideoLLMs lack reliable mechanisms for temporal grounding and motivate the development of models with more robust subject-event association.", "published": "2026-11-21", "comment": "EACL 2027", "url": "https://arxiv.org/abs/2605.27101"}]}, "rep": {"name": "三维表示与重建", "papers": [{"id": "2610.37036", "title": "GraftRay: Physically Based Mesh Insertion into Gaussian Splatting Scenes via Path Tracing", "authors": ["Jinxin Ai", "Matthias Nießner"], "abstract": "We present GraftRay, a unified method for physically consistent insertion of mesh objects into 2D and 3D Gaussian Splatting (2DGS/3DGS) indoor scenes, accounting for lighting interactions between objects and their surroundings. We lift albedo, roughness, metallic and normals from diffusion-based 2D priors onto the Gaussians by back-projection, model windows and lamps as analytic area emitters, and recover their absolute radiance from ordinary LDR captures with a low-dimensional fit over unit-radiance bases. A path tracer over Gaussians and meshes then produces view-consistent shading, interreflections and soft shadows, which are composited onto the original reconstruction by differential rendering, preserving the untouched background. On synthetic, real and generated scenes, GraftRay outperforms recent insertion and inverse-rendering baselines in image fidelity and shadow accuracy at competitive cost, and users prefer its lighting and shadows over those of the baselines.", "published": "2026-11-22", "comment": "8 pages + references, 8 figures, 2 tables", "url": "https://arxiv.org/abs/2610.37036"}, {"id": "2608.04701", "title": "UniWorld-View: Large-Baseline View Synthesis via Video Diffusion Models", "authors": ["Wangbo Yu", "Haiyang Zhou", "Chaoran Feng", "Xunyu Zhou", "Li Yuan"], "abstract": "Novel view synthesis from casually captured monocular images and videos offers a practical route to immersive content creation without dedicated multi-view capture. However, the limited viewpoint coverage of such inputs leaves scene geometry insufficiently constrained, restricting the ability of reconstruction-based methods, such as neural radiance fields (NeRF) and 3D Gaussian Splatting (3DGS), to render views far from the observed viewpoints. Generative approaches leverage learned visual priors to synthesize unobserved content, but maintaining geometric consistency and precise camera control remains challenging under large viewpoint changes. We present UniView, a unified framework for large-baseline novel view synthesis and scene generation from monocular images and videos. Central to our approach are an occlusion-aware point cloud renderer and a dual-branch conditioning mechanism. The renderer uses triple reprojection to identify and filter unreliable projections under large viewpoint changes. The conditioning mechanism integrates the resulting geometric guidance with source-view appearance within the video diffusion model, enabling precise camera control while preserving visual details and synthesizing unobserved content. To extend view synthesis to scene generation, we introduce a two-stage generation strategy that decouples viewpoint changes from temporal evolution. This strategy produces dense, synchronized multi-view videos that provide additional supervision for dynamic Gaussian Splatting, enabling more complete 4D generation from monocular observations. Extensive evaluations across static and dynamic scenes demonstrate the effectiveness of UniView in novel view synthesis and scene generation, combining precise camera control with geometric consistency and visual fidelity.", "published": "2026-11-23", "comment": "Project Homepage: https://zhouhyocean.github.io/uniworld-view/ Code: https://github.com/PKU-YuanGroup/UniWorld-View", "url": "https://arxiv.org/abs/2608.04701"}, {"id": "2611.28802", "title": "Not All Directions Are Flat: Decomposed-Gradient Flatness for Sparse-View 3D Gaussian Splatting", "authors": ["Ungbae Yoon", "Kwanyoung Kim"], "abstract": "Many applications of novel view synthesis, such as augmented reality and robotics, can afford only a few input views, since dense capture is costly. With such sparse views, however, 3D Gaussian Splatting (3DGS) overfits the training views and degrades at unseen viewpoints. Among the approaches to this problem, flat-minima optimization treats the Gaussians as trainable parameters and steers training toward flat minima, which generalize better, by perturbing the Gaussians with random noise or along the training gradient. However, these perturbations ignore their direction relative to the other training views. Interestingly, we find that the direction of the perturbation determines whether it improves generalization. Specifically, we decompose the gradient of each training view into a component parallel to the average gradient of all views, on which the views agree, and an orthogonal component, on which they disagree. Perturbing along the orthogonal component improves generalization, whereas perturbing along the parallel component does not. We further find that the flatness correction often opposes the reconstruction gradient, shrinking or even reversing the reconstruction step. Based on these findings, we propose DecoFlat, which perturbs each Gaussian along the orthogonal component together with random noise. Furthermore, we introduce a conflict-aware correction, which removes the part of the flatness correction that opposes the reconstruction gradient, and a rescheduling of the spherical-harmonics color, which suppresses the overfitting of view-dependent appearance. Extensive experiments demonstrate that DecoFlat, as a plug-in optimizer, consistently improves vanilla 3DGS and a wide range of sparse-view 3DGS methods.", "published": "2026-11-21", "comment": "19 pages, 13 figures, 11 tables", "url": "https://arxiv.org/abs/2611.28802"}, {"id": "2611.29236", "title": "Complementary Geometry in Gaussian Splatting", "authors": ["Mingle Jiang", "Jikui Zhou", "Chenghan Lyu", "Rui Xu", "Yunke Wang", "Chang Xu"], "abstract": "Gaussian Splatting has achieved high visual quality in novel view synthesis, but the accuracy of its rendered geometry remains a challenge. In particular, the rendered depth is computed as an opacity-weighted average along each ray, which may not correspond to the actual scene surface. In this paper, we observe that depth predictions from different views of the same frozen Gaussian representation exhibit complementary errors, allowing us to improve novel-view geometry using information from other views without modifying the original representation. Based on this observation, we propose REVEAL, a general framework that selectively refines novel-view depth using complementary geometric information. Specifically, we first reproject depth predictions from source views to the target view and combine them using robust multi-view consensus. We then introduce a learned selection mechanism to determine whether the candidate depth is more accurate than the original prediction, based on the expected reduction in depth error. In addition, we introduce RIG, a real-world benchmark captured with synchronized RGB-D cameras, which provides ground-truth depth for evaluating both static and dynamic reconstruction models. Experiments on 6 Gaussian Splatting backbones across 3 benchmarks show that REVEAL consistently improves depth accuracy while maintaining comparable rendering quality.", "published": "2026-11-22", "comment": "14 Pages, supplementary material included", "url": "https://arxiv.org/abs/2611.29236"}, {"id": "2610.36853", "title": "D4GS: Efficient Gaussian Splatting SLAM with Depth Priors", "authors": ["Da Li", "Yihan Zang", "Ivan Viola", "Zeyu Wang", "Dominik Engel"], "abstract": "Achieving high-quality reconstruction and responsive camera tracking remains challenging for monocular RGB Gaussian splatting SLAM under a limited optimization budget. We present an online system that addresses this challenge by combining learned geometric priors with explicit geometric camera tracking, which efficiently performs camera tracking while maintaining the map to keep the predicted depth scale consistent. A frozen depth model serves as a virtual RGB-D sensor, providing depth estimation from monocular video. An explicit geometric solver then estimates camera pose through feature reprojection, and a streaming Gaussian mapper integrates the resulting observations into a dense scene representation. Extensive experiments on indoor and outdoor datasets show that our method significantly improves reconstruction quality over existing approaches, achieving over 10 FPS on a single RTX 4090 and delivering almost twice the throughput of the evaluated fastest prior SLAM systems on the 7-Scenes dataset.", "published": "2026-11-23", "comment": "11 pages, 5 figures", "url": "https://arxiv.org/abs/2610.36853"}, {"id": "2611.31023", "title": "WildAnySplat: Feed-Forward 3D Gaussian Splatting in the Wild", "authors": ["Richard Shaw", "Arthur Moreau", "Athanasios Papaioannou", "Thomas Tanay", "Zhensong Zhang", "Eduardo Pérez-Pellitero"], "abstract": "We present WildAnySplat, a feed-forward 3D Gaussian Splatting framework that enables robust novel-view synthesis from in-the-wild multi-view images. Unlike controlled captures, real-world images often contain multi-view inconsistencies caused by transient occluders, illumination changes, and camera ISP, which degrade the quality of existing feed-forward reconstruction methods. To address this challenge, we introduce a student-teacher framework that learns transient-robust and appearance-consistent 3D representations. A teacher network operates on clean images, while a student processes the corresponding in-the-wild inputs. The teacher provides clean supervision to guide the student toward a consistent canonical representation. Since paired clean and in-the-wild data are scarce, we use a hybrid data strategy, combining real paired captures, synthetic augmentations, and pseudo-clean labels generated from optimization-based reconstructions, bridging the domain gap between synthetic and real-world data. We adopt a transformer architecture with dedicated DPT heads for camera pose, depth, and Gaussian prediction. We additionally predict per-view transient masks to reweight photometric supervision and suppress unreliable Gaussians. To account for cross-view appearance variation, we incorporate a bilateral grid module that models per-image color transformations and enables recovery of a canonical radiance representation. Experiments on challenging in-the-wild benchmarks show that WildAnySplat improves robustness to transient occlusions and appearance variation while retaining the fast inference of feed-forward Gaussian Splatting.", "published": "2026-11-23", "comment": "Accepted to SIGGRAPH Asia 2026 (Conference Papers). Project page: https://wildanysplat.github.io/ ; Supplementary material: https://wildanysplat.github.io/wildanysplat_supp.pdf", "url": "https://arxiv.org/abs/2611.31023"}, {"id": "2611.28636", "title": "SemGuard: Semantics-Decoupled Watermarking for Gaussian Splatting", "authors": ["Yingying Shi", "Zhong Zhou", "Bin Zhou"], "abstract": "Gaussian Splatting provides an efficient representation for high-fidelity rendering of static and dynamic 3D scenes, motivating the copyright protection of Gaussian assets. In CLIP-guided Gaussian watermarking, a universal message decoder pretrained on textual watermark representations is subsequently applied to visual features containing both watermark information and scene-dependent semantics. However, text-only pretraining does not explicitly account for the semantic interference encountered during watermark extraction. To address this challenge, we propose SemGuard, a simple yet effective semantics-decoupled watermarking framework that learns to suppress scene-dependent semantic interference during universal message decoder pretraining. Specifically, SemGuard combines message-related CLIP text features with message-independent visual features extracted from unwatermarked scene images, constructing training representations with controllable semantic interference relevant to the target Gaussian assets. A progressive semantic interference curriculum gradually increases the contribution of visual features, allowing the decoder to first learn reliable message representations and then adapt to increasingly strong scene-dependent semantic interference. After pretraining for a given message length and semantic image pool, the decoder is frozen and reused across multiple Gaussian assets whose visual semantics are covered by the pretraining data. Experiments on static and dynamic Gaussian Splatting assets demonstrate improved rendering fidelity alongside reliable watermark extraction, while evaluations on static assets further show enhanced robustness against image-space distortions.", "published": "2026-11-21", "comment": "10 pages, 3 figures. Submitted to IEEE Transactions on Multimedia (under review)", "url": "https://arxiv.org/abs/2611.28636"}, {"id": "2611.29388", "title": "SpectralGS: Spectral Gaussian Splatting for Unsupervised Spectral Super-Resolution", "authors": ["Qiaoying Qu", "Bin Pan", "Chen Jia", "Haiyang Xu", "Xia Xu", "Zhenwei Shi"], "abstract": "Unsupervised spectral super-resolution aims to recover spectral information from RGB images without paired hyperspectral data. However, the limited spectral information in RGB observations makes learning an effective spatial-spectral representation challenging, requiring the incorporation of structured spectral modeling with sensor imaging. In this paper, we propose SpectralGS, a spectral Gaussian splatting framework comprising two components: Shared Spectral Gaussian Representation and Spectral Response Projection Rendering. The representation module constructs a continuous spatial-spectral representation via shared spectral and local spatial Gaussian primitives, exploiting the low-rank spectral structure of hyperspectral images. The rendering module utilizes the spectral response function (SRF) to apply integral projection to the continuous representation, blending it to generate an RGB image. Consistency between the rendered and observed RGB images provides training supervision. Our main contribution is a Gaussian splatting framework that integrates structured continuous spatial-spectral representation with imaging response-based rendering, enabling unsupervised spectral reconstruction. Extensive experiments demonstrate that our method outperforms current state-of-the-art methods.", "published": "2026-11-22", "comment": null, "url": "https://arxiv.org/abs/2611.29388"}, {"id": "2611.30102", "title": "LMnOP: Pruning 3D Gaussian Splatting via Leave-Many-Out Importance", "authors": ["Sunjae Jeong", "Jaeseung Kim", "Hyoseok Hwang"], "abstract": "3D Gaussian Splatting renders photorealistic views in real time. However, a single scene often needs millions of Gaussians, so these models are costly to store and render. Pruning reduces this cost by keeping a subset of the Gaussians. A common score is the leave-one-out importance, which is the loss increase when a Gaussian alone is removed. At high pruning ratios, many Gaussians are removed together, so Gaussians that are redundant alone but essential together are lost. We present LMnOP (Leave-Many-Out Pruning), which estimates the importance of each Gaussian under the removal of the other Gaussians. This leave-many-out importance is the average loss increase when a Gaussian is removed while the others are also removed at random. We compute the exact mean and variance of each pixel's color under random removal in closed form, and approximate the importance from them without sampling removal patterns. We refine each Gaussian's probability of remaining with its importance and prune once at the end. Without fine-tuning, LMnOP achieves the best results in 16 of 18 metrics on three datasets at 90% and 99% removal. It improves SSIM and LPIPS over GaussianPOP in all 13 scenes.", "published": "2026-11-23", "comment": "9 pages, 5 figures, 5 tables", "url": "https://arxiv.org/abs/2611.30102"}, {"id": "2611.30283", "title": "AdvMTO: Multimodal and Temporal Adversarial Object Attacks via 2D Gaussian Splatting for BEV-Based 3D Object Detection", "authors": ["Zhiyang Cui", "Hao Tan", "Ruonan Li", "Shibin Wu", "Junjian Zhang", "Hong'an Lin", "Zhaoquan Gu"], "abstract": "Adversarial object attacks pose a threat to BEV-based 3D object detectors in autonomous driving. Existing attacks typically target a single modality, coordinate camera and LiDAR observations at the current timestamp, or model temporal persistence mainly in camera streams. Without a unified construction of current and historical observations, attacks can leave part of the detector's accumulated evidence unsuppressed, limiting their effectiveness. In this paper, we propose AdvMTO, a 2D Gaussian Splatting (2DGS) framework for suppressing detection of persistent adversarial objects. Its oriented surfels encode appearance, geometry, and opacity in one object state, from which camera images and scanline LiDAR returns are generated. AdvMTO then constructs current and historical inputs through detector-native processing, regenerating LiDAR returns in each native source sweep for fusion detectors. We optimize bounded appearance perturbations for each detector, propagating gradients through historical BEV memory for temporal camera detectors. For fusion detectors, bounded geometry refinement along local normals further perturbs both sensing modalities. Experiments on nuScenes demonstrate effective suppression of traffic-cone detection across three BEV detectors. Temporal ablations further highlight the importance of detector-native history modeling for both attack construction and optimization.", "published": "2026-11-23", "comment": null, "url": "https://arxiv.org/abs/2611.30283"}, {"id": "2611.30351", "title": "NNS-GS: Non-Local Neural Scattering for Relightable Gaussian Splatting", "authors": ["Shiyu Liang", "Yang Gao", "Lili Wang", "Aimin Hao", "Beibei Wang"], "abstract": "Creating relightable 3D assets of translucent objects is challenging because changing the illumination at one surface location can affect the appearance elsewhere through subsurface scattering. Existing Gaussian-based scattering models typically predict scattering from local features, making this dependence difficult to capture. We present Non-Local Neural Scattering for Gaussian Splatting (NNS-GS), which learns non-local scattering together with geometry-guided local reflection. The scattering module learns how illumination from light-visible surface regions in light space contributes to the shading point in view space, conditioned on regional diffuse responses and spatial relationships. The reflection module supplies these diffuse responses and uses additional geometric guidance to better capture specular highlights and sharp shadow boundaries. To reduce component mixing and support controllable scattering appearance, anchor-based progressive training establishes the diffuse-scattering base before introducing specular reflection and supervises the components separately. Under calibrated point lighting, NNS-GS improves mean PSNR over existing methods by 2.47 dB and 0.81 dB on the synthetic and real translucent scenes, respectively. Additional synthetic comparisons further show that NNS-GS better matches the reference when adjusting scattering attenuation.", "published": "2026-11-23", "comment": null, "url": "https://arxiv.org/abs/2611.30351"}, {"id": "2611.30602", "title": "GSDet: Gaussian Splatting for Oriented Object Detection", "authors": ["Zeyu Ding", "Jiaqi Zhao", "Yong Zhou", "Wen-liang Du", "Hancheng Zhu", "Rui Yao"], "abstract": "Oriented object detection has advanced with the development of convolutional neural networks (CNNs) and transformers. However, modern detectors still rely on predefined object candidates, such as anchors in CNN-based methods or queries in transformer-based methods, which struggle to capture spatial information effectively. To address the limitations, we propose GSDet, a novel framework that formulates oriented object detection as Gaussian splatting. Specifically, our approach performs detection within a 3D feature space constructed from image features, where 3D Gaussians are employed to represent oriented objects. These 3D Gaussians are projected onto the image plane to form 2D Gaussians, which are then transformed into oriented boxes. Furthermore, we optimize the mean, anisotropic covariance, and confidence scores of these randomly initialized 3D Gaussians, using a decoder that incorporates 3D Gaussian sampling. Moreover, our method exhibits flexibility, enabling adaptive control and a dynamic number of Gaussians during inference. Experiments on 3 datasets indicate that GSDet achieves AP$_{50}$ gains of 0.7\\% on DIOR-R, 0.3\\% on DOTA-v1.0, and 0.55\\% on DOTA-v1.5 when evaluated with adaptive control and outperforms mainstream detectors.", "published": "2026-11-23", "comment": "IJCAI 2025", "url": "https://arxiv.org/abs/2611.30602"}]}, "ff": {"name": "前馈几何（VGGT 一系）", "papers": [{"id": "2611.22244", "title": "PhyVGGT: Feed-Forward Articulated Object Reconstruction from Monocular Videos", "authors": ["Qi Shao", "Zhihao Cao", "Shuhao Zhai", "Anh Nguyen", "Hong Liang", "Liang Li", "Baoru Huang"], "abstract": "Reconstructing an articulated object with its 3D movable parts, joint parameters and unseen articulation states from an uncalibrated monocular video is essential for robot manipulation and interactive digital twins. Existing per-scene optimisation methods require minutes to hours and external depth or camera poses, whereas feed-forward 3D foundation models reconstruct dense point maps in one pass without segmenting movable parts or inferring joints. Even on these monocular point maps, regressing or fitting continuous joints directly fails on casual videos, since cross-frame attention blurs moving part boundaries in deep layers, underestimates motion along the viewing ray and leaves continuous axes ill-conditioned under small opening angles. To address these challenges, we propose PhyVGGT, a single-pass framework on a frozen 3D foundation model that anchors moving-part matching and closed-form joint estimation to the undistorted geometry of the stationary base. First, our Part and Motion Decoder fuses intermediate per-frame tokens with global tokens and references part queries to a static-base query to segment 3D parts, align point maps on the static base and predict learned Bingham priors. Second, our Kinematic Inference Layer fits an orthogonal Manhattan frame to static surface normals, selects the joint axis in closed form under a Bingham posterior combining pairwise motion scatter with the learned priors, and solves a linear system for the hinge pivot to drive unseen states. Trained solely on synthetic data, PhyVGGT achieves state-of-the-art monocular performance across five benchmarks, outperforming FAMOS and monocular ArtiPoint, surpassing posed RGB-D ArtiPoint in median error, and running in 6.8 s per 48-frame video against hours of per-scene optimisation in Articulat3D. Project page: https://phyvggt.github.io.", "published": "2026-11-22", "comment": "10 pages, 5 figures, 7 tables. Project page: https://phyvggt.github.io", "url": "https://arxiv.org/abs/2611.22244"}, {"id": "2611.28591", "title": "CAR3T: Generalizable Calibration-Guided Reference-View Attention Reuse for Multi-View 3D Transformers", "authors": ["Lan Wei", "Haosong Peng", "Sicheng Tian", "Tianyu Qi", "Wenchao Xu", "Lei Xue", "Yufeng Zhan", "Yuanqing Xia"], "abstract": "Feed-forward multi-view 3D reconstruction relies on global attention for cross-view aggregation, but the attention cost grows quadratically with the number of views, making inference increasingly expensive for larger inputs. Existing acceleration methods compress tokens or sparsify attention, potentially losing geometric detail or restricting cross-view aggregation while leaving redundancy among attention outputs underexploited. We observe similar cross-view attention distributions in certain layers, revealing an opportunity to reduce repeated global aggregation through output reuse. However, the layers suitable for reuse vary with the input, and reusing one layer alters the features received by later layers. Similarity at individual layers therefore cannot characterize the combined effect of multiple reuse decisions on output drift. To address these challenges, we propose CAR3T, a training-free framework combining reference-view attention output reuse with offline risk calibration and online dynamic layer selection. Calibration models cumulative reuse risk, while online selection adapts reuse to each input under a calibrated budget. CAR3T retains all input tokens and attends to the keys and values of all views, reducing the core attention computation in selected layers from quadratic to linear. Experiments on VGGT, DA3, and $π^3$ show forward speedups up to $1.41\\times$ with at most 100 views and $1.75\\times$ on longer sequences, with accuracy trade-offs across backbones and datasets.", "published": "2026-11-21", "comment": null, "url": "https://arxiv.org/abs/2611.28591"}, {"id": "2606.04493", "title": "Smooth Inliers, Erratic Outliers: Frequency-Aware Mamba for Two-View Correspondence Learning", "authors": ["Zhihua Wang", "Yifeng Gao", "Yunhao Feng", "Rui Pan", "Zhouyuan Ma", "Baiheng Zhao", "Zixing Chen", "Yanping Li", "Yizhang Liu", "Xingjun Ma"], "abstract": "When shown matches between two photographs of the same cathedral, people can tell at a glance which ones are wrong: a window matched to its look-alike jumps against its neighbors, while correct matches shift together. Two-view correspondence learning, also called correspondence pruning, asks a network to make this judgment for thousands of candidate matches, most of which are wrong. Mamba, a fast sequence model, now drives strong pruners, but it reads the matches as a plain sequence, and whether its scan can capture such agreement is unclear. We propose SFMambaNet, which scans the matches cluster by cluster, so that correct matches vary slowly along the sequence while wrong ones stay erratic, and filters the scanned features with learnable frequency-domain gates between its forward and backward passes. On camera pose estimation, outlier removal and homography estimation, we find that SFMambaNet outperforms spatial-domain Mamba baselines with about two million parameters. Contrary to the usual expectation that such gains come from extra capacity, we find that a parameter-free low-pass filter beats point-wise layers as large as the gates. The learned gates turn low-pass on their own and make the scan far less sensitive to how the matches are shuffled. Together, these results show that frequency is a natural language for describing agreement between correspondences, with implications for other sequence models that must read unordered sets, such as point clouds and graphs.", "published": "2026-11-22", "comment": "26 pages, including appendices. Corrected and completed bibliographic metadata in the references", "url": "https://arxiv.org/abs/2606.04493"}, {"id": "2611.30769", "title": "Screening for nonrigidity in structure from motion using projected reprojection residuals", "authors": ["Íñigo Cirauqui-Viloria"], "abstract": "Sparse structure from motion (SfM) assumes a static scene, yet deformation may still yield plausible reconstructions. Reprojection-error summaries discard how errors are arranged across points and views. We propose a diagnostic that first removes residual components explainable by small point and camera adjustments and simple spatial trends that change over time. It then measures alignment with fixed spatial and temporal patterns. The diagnostic uses one estimated SfM reconstruction and provides screening evidence rather than a physical deformation estimate. Across four synthetic tubular families, the diagnostic detected all eight acquisitions with prescribed motion, compared with five or six for summaries of reprojection-error magnitude. Each family's cutoff was the highest static score among the other three families, so the static acquisition with the highest score also screened positive. With the same cutoffs, the diagnostic retained positive detections in 19 of 20 reconstruction variants spanning changes in appearance and reconstruction pipeline, with one numerical abstention. These findings show that the arrangement of reprojection errors across points and views can reveal inconsistencies that their magnitudes alone miss. The four families were known during development, and the transfer variants reused two of them. Within this setting, the diagnostic offers a practical way to flag a plausible reconstruction for closer inspection using only its estimated cameras, 3D points and image observations.", "published": "2026-11-23", "comment": "34 pages including 19 pages of supplementary material. 5 main figures and 5 supplementary figures", "url": "https://arxiv.org/abs/2611.30769"}, {"id": "2611.28649", "title": "S-Mind: Internalizing Multi-View Geometry for Spatial Intelligence", "authors": ["Muxin Fu", "Peike Yu", "Guibin Zhang", "Wenrui Zhou", "Runze Liu", "Lang Feng", "Fuchao Yang", "Feng Chen", "Yixuan Li", "Mengao Zhang", "Shiying Zhang", "Wen Shen", "Ling Pan", "Shuicheng Yan", "Bo An"], "abstract": "Spatial intelligence, the ability to reason about 3D space from visual observations, becomes essential as multimodal large language models (MLLMs) move into the physical world. Beyond perceiving each view, it rests on two cornerstones of human cognition: fusing multiple views into one coherent 3D scene and mentally transforming that scene to new viewpoints as reasoning unfolds. Yet our spatial probes reveal that MLLMs largely lack both capabilities, even after spatial fine-tuning. We therefore present S-Mind, which internalizes multi-view geometry within the MLLM through a compact set of spatial tokens. It supervises these tokens to hold the fused 3D scene and re-emits them to re-express this scene from every viewpoint the reasoning adopts. Across four spatial benchmarks, S-Mind improves its Qwen3.5 backbones by up to 22.26 points and surpasses frontier general models such as GPT-6-Astra (+0.45), Kimi-K3.1-Pro (+1.97), and GLM-5.3-Flash (+7.80) in average accuracy. Moreover, the same probes confirm that it acquires both capabilities, reaching fusion and transformation accuracies of 65.11% and 82.17%, against at most 16.02% and 37.28% for the baselines. At inference, S-Mind also runs about 100x faster than a tool-based agent on the same backbone. Instilled through these spatial tokens during training, spatial capability becomes intrinsic to the backbone and persists even when the tokens are withheld, offering a promising path toward spatial intelligence in MLLMs.", "published": "2026-11-21", "comment": null, "url": "https://arxiv.org/abs/2611.28649"}, {"id": "2611.28673", "title": "ViewAgent3D: A Training-Free Multi-View Pipeline for 3D Scene Understanding", "authors": ["Sarosij Bose", "Arindam Dutta", "Konstantinos Karydis", "Amit K. Roy Chowdhury"], "abstract": "3D scene understanding tasks are often approached by building explicit 3D scene representations or by training specialized multi-modal models over point clouds, voxels, or scene graphs. We take a complementary view: for many queries, the main bottleneck is not the absence of a stronger 3D representation but the selection of a small subset of multi-view RGB views that actually makes the query answerable. We present a training-free, query-conditioned multi-view pipeline that performs diverse tasks using only 2D images and a set of tools used purely for inference. Our method first decomposes each query into a set of concepts that identify unique attributes that assist with reasoning. This drives a coarse-to-fine evidence selection process: a coarse retrieval selects and scores all views, a diversity-aware selector reduces redundancy, and a reranking stage helps shortlist views by target visibility or answerability. The resulting evidence is optionally grounded for queries that benefit from explicit localization, and a self-verification step helps refine the final response, especially for open-ended cases. Despite using no task-specific training and no explicit 3D representations at inference time, our approach provides approximately 10% gain on 3D VQA and 5% gain on dense captioning and Embodied QA while being applicable across different scenarios. We further propose a unique judge-based evaluation system, motivating a judge who takes into account many semantically correct or partially correct answers, thereby improving holistic scene understanding.", "published": "2026-11-21", "comment": null, "url": "https://arxiv.org/abs/2611.28673"}, {"id": "2611.28979", "title": "AlignHand: Multi-View Hand Reconstruction from a Frozen Monocular Prior", "authors": ["Zhilu Yang", "Kun Yang", "Shiyan Wang", "Anqi Xu", "Xinran Huang", "Yizheng Jiao", "Huan Yang", "Rolandos Alexandros Potamias"], "abstract": "Modern monocular hand estimators recover detailed 3D meshes from individual images, yet effectively leveraging their predictions across multiple views remains challenging. Independently predicted meshes can disagree in scale, placement, and articulation, limiting the integration of complementary multi-view information. Hence, we present AlignHand, a calibrated multi-view framework that builds on a frozen monocular hand reconstruction prior to align and enhance its predictions. Specifically, AlignHand refines cross-view joint observations and estimates their reliability to establish a shared metric reference for alignment. Once the meshes are brought into a common frame, their complementary surface evidence is selectively fused across anatomical regions, followed by pixel-aligned refinement that predicts bounded residual displacements from local image features. This global-to-local integration enables AlignHand to exploit complementary observations while preserving the strong monocular prior. Extensive experiments on DexYCB-MV, HanCo, and HO3D-Eval-MV demonstrate that AlignHand achieves the lowest MPVPE and MPJPE among the compared methods under the respective evaluation protocols, reducing MPVPE by 30.1%, 29.1%, and 8.0%, respectively, compared with a matched geometry baseline.", "published": "2026-11-21", "comment": "18 pages, 6 figures. Project page and code: https://ada-zy2425.github.io/AlignHand/", "url": "https://arxiv.org/abs/2611.28979"}, {"id": "2611.29068", "title": "ViewPACT: Multi-View Geometric Augmentation and Pose-Action Co-Training for Viewpoint-Robust Manipulation", "authors": ["Chenglang Tu", "Feng Chen", "Ruizhe Liu", "Pei Zhou", "Binbin Huang", "Chen Xu", "Yanchao Yang", "Yi Ma", "Shenghua Gao"], "abstract": "Image policies are scalable but remain brittle to camera viewpoint changes. On LIBERO, we identify proprioception as an input shortcut: masking robot states sharply degrades several policies, while retraining from images alone recovers much of the loss. We introduce ViewPACT, an image policy trained with privileged geometric supervision. Auxiliary objectives recover end-effector and task-relevant object poses in the camera frame, while deployment requires only RGB observations. Joint geometric supervision improves mean simulation success from 37.4% to 78.4% under unseen external-camera viewpoints, with more modest gains under separately evaluated object, scene, and camera-intrinsic shifts. Across four real-robot tasks, combining simulated and real-image geometric supervision achieves 68.1% mean success, versus 3.1% for fixed-view behavior cloning and 30.6% for the strongest evaluated alternative. These results support geometric supervision for viewpoint robustness in the evaluated fixed-view demonstration setting.", "published": "2026-11-21", "comment": "9 pages, 5 figures, 5 tables", "url": "https://arxiv.org/abs/2611.29068"}, {"id": "2611.29112", "title": "Bridging Blind Spots With Words: Decentralized Multi-View Spatial Reasoning via Language-Constrained Communication", "authors": ["Soumyabrata Chaudhuri", "Joydeep Ghosh"], "abstract": "As multimodal LLMs (MLLMs) get increasingly used as collaborative partners across embodied robotics, AR/VR, and multi-user systems, spatial reasoning is now often distributed across agents with partial environment visibility, necessitating spatial reasoning integration. Prior work in language-mediated spatial integration is however strictly limited to simplified two-agent scenarios. To address this gap, we first formalize the general problem of decentralized multi-view spatial reasoning, where N agents observe distinct viewpoints, exchange budget-constrained natural language messages, and collaborate to enable a listener to answer spatial queries. We then introduce a novel multi-view spatial benchmark to isolate queries that demand non-trivial multi-view integration. Through an extensive empirical study, we discover that the penalty of restricting decentralized spatial reasoning to natural language with limited budget is far smaller than suggested by prior two-agent literature. Nevertheless, we observe that substantial headroom still remains for multi-agent spatial reasoning in this setting, as evidenced by a significant gap between current centralized performance and an oracle best-of-K ceiling. Moreover, we show that reinforcement learning with credit assignment substantially bolsters the decentralized model, effectively closing the gap with the centralized baseline.", "published": "2026-11-22", "comment": "17 pages, 13 tables, 4 figures", "url": "https://arxiv.org/abs/2611.29112"}, {"id": "2611.29753", "title": "DREAM: Dual-Memory Reasoning for Anticipatory 3D Perception in Autonomous Driving", "authors": ["Sriram Mandalika", "Athira Nambiar"], "abstract": "Autonomous driving systems must not only interpret the current scene but also anticipate perceptual challenges such as occlusions, sparse observations, and recurring failure patterns. However, most existing LiDAR semantic segmentation methods operate in a frame-centric manner, processing each scan independently and discarding past contextual experience, which limits robustness under dynamic scene changes. We propose DREAM, a Dual-memory REAsoning framework for continual LiDAR seMantic segmentation that reframes perception as an experience-driven and anticipatory process. DREAM maintains two complementary memory banks in a strictly online setting: a latent memory that stores compact semantic abstractions of previously observed scenes, and an error memory that records representations associated with uncertain predictions. At each timestep, relevant memory entries are retrieved via cosine similarity and integrated into the feature space through a lightweight modulation mechanism, enabling the model to reinforce consistent semantic patterns while suppressing recurring failure modes. The backbone remains frozen and no past scans are replayed, ensuring computational efficiency and bounded memory growth. Extensive experiments on multiple large-scale LiDAR benchmarks demonstrate that DREAM achieves state-of-the-art performance, with consistent improvements on dynamic and small-scale objects, highlighting the effectiveness of persistent and error-aware memory for robust long-horizon perception.", "published": "2026-11-22", "comment": "CVPR 2026 Workshop", "url": "https://arxiv.org/abs/2611.29753"}, {"id": "2611.30787", "title": "BridgeMVS: Bridging Multi-View Stereo and Monodepth via Bidirectional Dynamic Fusion", "authors": ["Jianfei Jiang", "Haochen Yu", "Qiankun Liu", "Rui Yang", "Hongyuan Liu", "Xianglong Meng", "Jiansheng Chen", "Huimin Ma"], "abstract": "Multi-View Stereo (MVS) and Monocular Depth Estimation (MDE) provide complementary cues for dense 3D reconstruction. While MVS leverages explicit geometry for metric depth, it struggles in challenging regions where feature matching is unreliable. Conversely, MDE provides robust structural priors but typically yields scale-ambiguous results. Existing hybrid methods mainly exploit monocular cues in a unidirectional manner, leaving the mutual enhancement between MDE and MVS insufficiently explored. To address this limitation, we propose BridgeMVS, a unified cascaded multi-stage MVS framework that bridges monocular depth features and multi-view cost volume representations through Bidirectional Dynamic Fusion (BDF). At each stage, BDF performs dynamic mono-to-cost and cost-to-mono updates, where monocular structural features guide cost volume refinement for more robust MVS depth estimation, while multi-view geometric evidence recalibrates monocular representations to improve their metric-scale consistency. Furthermore, the fused monocular and multi-view representations are progressively propagated from coarse to fine stages and constrained by stage-wise relative-scale MDE supervision and metric-scale MVS supervision, enabling cross-branch interactions to benefit subsequent high-resolution depth estimation. In addition, BDF is designed as a plug-and-play module that can be conveniently integrated into existing cascaded MVS frameworks. Extensive experiments demonstrate that BridgeMVS achieves state-of-the-art performance on the DTU, Tanks-and-Temples, and ETH3D benchmarks, while simultaneously boosting the accuracy of monocular depth estimation. Notably, BridgeMVS ranks first on both the Tanks-and-Temples Intermediate and Advanced benchmarks. The source code is available at \\href{https://github.com/JianfeiJ/BridgeMVS}{https://github.com/JianfeiJ/BridgeMVS}.", "published": "2026-11-23", "comment": "Accepted by NeurIPS 2026", "url": "https://arxiv.org/abs/2611.30787"}, {"id": "2611.31140", "title": "HoloSplat: Real-Time Token Streaming for Feed-Forward Human Reconstruction", "authors": ["Chaofan Li", "Qihan Ding", "Shihan Wang", "Zhehao Shen", "Boyu Shen", "Quanyu Chen", "Haoyu Wu", "Lan Xu", "Xin Lou"], "abstract": "Live free-viewpoint video streaming of humans enables immersive telepresence and interactive XR applications. However, this requires reconstructing each frame in real time, transmitting the data within strict bandwidth budgets, and decoding it on lightweight client GPUs. Existing approaches, whether relying on per-frame optimization or feed-forward inference, generate massive 3D Gaussian payloads that exceed practical streaming limits, while aggressive compression severely degrades rendering quality. In this work, we present HoloSplat, a real-time streaming framework for human-centric volumetric video. HoloSplat splits a feed-forward reconstructor before its Gaussian head, introducing a multi-rate streaming codec driven by server-side token compression and client-side token restoration. On the server side, we apply opacity-guided token pruning, PCA-based dimensionality reduction, and lossless geometry coding for token anchors. On the client side, a feature reconstruction hypernetwork is fused into the Gaussian head to recover compression-induced quality loss. Furthermore, we introduce Neural Session Calibration (NSC), which rapidly fine-tunes the Gaussian head online using incoming camera views during a warm-up phase. This resolves quality degradation from novel camera parameters and varying capture conditions with zero per-frame overhead. In our evaluations, HoloSplat averages 32.2 FPS on four RTX 5090 GPUs at 50 Mbit/s. It decodes each frame into 3D Gaussians in 22.1 ms on an RTX 3050 Ti laptop GPU, transmitting 22.8$\\times$ less data than uncompressed float32 Gaussians, while calibrated decoding improves PSNR by 1.050 dB.", "published": "2026-11-23", "comment": "43 pages including supplementary material, 20 figures. Project page: https://heaticy.github.io/HoloSplat/", "url": "https://arxiv.org/abs/2611.31140"}]}, "wm": {"name": "世界模型", "papers": [{"id": "2611.30898", "title": "World Models as Native Latent Action Models", "authors": ["Qinyue Li", "Weijie Qiao", "Qingyi Tao", "Zerui Gong", "Zhe Yang", "Quanzhou Li", "Taolin Zhang", "Jinglin He", "Zhonghua Wu", "Chen Change Loy"], "abstract": "Large and diverse video sources, such as egocentric human video and heterogeneous robot recordings, carry rich dynamics but come either without actions or without a shared action space. Latent action models (LAMs) can recover these dynamics, but they train their inverse- and forward-dynamics models (IDM, FDM) from scratch, trading off pixel reconstruction against latent capacity and accuracy. Pretrained video world models natively generate high-fidelity dynamics, yet represent them densely, entangled across all layers. Viewing the world model as a LAM, we show that these dynamics can be extracted with minimal changes to the model. Native LAM operates one pretrained video diffusion transformer as both IDM and FDM, with learnable dynamics registers as the only causal bridge between the two, and trains on counterfactual temporal pairs that differ in motion alone, so that the registers distill a video's dynamics into a compact native latent action. We further propose a pretraining paradigm for vision-language-action (VLA) policies, Pretraining Actions from World models (PAWlicy), in which Native LAM serves as a dynamics teacher on large-scale video; unlike world action models, it never generates video. Native latent actions outperform existing LAMs on the LARY benchmark in both action classification and control regression, and replay the same motion on new robots, in new scenes, and from human hands to robots, although no transfer objective is used in training. With a 3.8B model, PAWlicy reaches a 93.6% average success rate on RoboTwin 2.0 trained with domain-randomized demonstrations, the highest among VLAs. On RoboDojo, it is competitive on every dimension we evaluate, and its Precision, evaluated by us, is on par with the leading leaderboard entries. On real robots, it improves over the pi_0.5 baseline on both tasks. Both stages use only public data and a publicly released world model.", "published": "2026-11-23", "comment": "19 pages, 7 figures, 6 tables. Project page: https://pawteam-eai.github.io/native-lam/", "url": "https://arxiv.org/abs/2611.30898"}, {"id": "2611.28553", "title": "WorldWeave: Rethinking Embodied Navigation through Cross-Task World Modeling", "authors": ["Xuan Yao", "Jiahao Zhang", "Rongjunchen Zhang", "Kaixuan Huang", "Junyu Gao", "Changsheng Xu"], "abstract": "Mobile embodied agents continuously alter their observations through their own motion, while external dynamics further shape future interactions. Different mobile embodied tasks therefore capture complementary patterns of state evolution, yet jointly learning world dynamics across such interactions remains less explored. We investigate this problem through Vision-and-Language Navigation (VLN) and Embodied Visual Tracking (EVT), which respectively involve navigation toward a stationary goal and interaction with a moving target. We propose WorldWeave, a cross-task world model that couples shared predictive dynamics with task-specific adaptation. Instead of conditioning state transitions on heterogeneous physical actions, WorldWeave learns latent actions from observed state changes via inverse-forward dynamics, establishing a shared transition representation across tasks. The resulting future-state predictions are adaptively integrated into task-specific representations for downstream decision making. Experiments across multiple VLN and EVT benchmarks demonstrate consistent improvements over specialized baselines.", "published": "2026-11-21", "comment": null, "url": "https://arxiv.org/abs/2611.28553"}, {"id": "2611.28666", "title": "RecallWorld: Episodic Memory for Persistent Embodied Video World Models", "authors": ["Sarosij Bose", "Gitika Karumuri", "Chenqi Li", "Allen Tu", "Srikumar Sastry", "Mellon Zhang", "Avinash Ravichandran", "Alexander Schwing", "Konstantinos Karydis", "Amit K. Roy Chowdhury"], "abstract": "Video world models generate plausible novel views but often lack persistent memory, failing to preserve a place's geometry and appearance when an agent revisits a scene. A central challenge is how previous views should be effectively used for creating memory. Reconstructing them independently underutilizes geometric constraints between nearby views, while repeatedly reconstructing a growing history can propagate later prediction errors into earlier geometry. We introduce RecallWorld, a persistent embodied video world model that jointly reconstructs short multi-view episodes into Scenelets while keeping geometry independent across episodes. Starting from a single source image, camera-aware ray lifting places perspective and native fisheye images in a common world frame, retaining wide-field content for perspective generation. Each generated segment extends the Scenelet memory and conditions subsequent generation. Coverage-based retrieval selects complementary Scenelets from the full history, while target-view visibility is resolved geometrically before appearance fusion, providing consistent memory conditioning for guiding subsequent generation. Across four datasets, RecallWorld improves revisit PSNR over the strongest evaluated baseline by 2.6 dB on partial revisits and 3.9 dB on full cycles, demonstrating substantially stronger preservation of scene identity across exploration and return.", "published": "2026-11-21", "comment": null, "url": "https://arxiv.org/abs/2611.28666"}, {"id": "2611.28779", "title": "Imagine Smarter, Drive Faster: Efficient World Modeling for Decision-Aware Autonomous Driving", "authors": ["Feiyang Jia", "Lin Liu", "Zhicheng Bao", "Caiyan Jia", "Ziying Song", "Shengkai Zhang", "Lina Han", "Yan Zhao", "Xiaoshuai Hao"], "abstract": "World models hold great promise for autonomous driving planning, yet their ability to imagine the future often comes at a formidable computational cost. Efficiency efforts, such as knowledge distillation and domain-specific pre-training, often shift this burden to costly teachers or training pipelines, leaving lightweight world modeling an open challenge. We introduce FastWorld, a natively lightweight world-model framework for efficient autonomous driving planning. FastWorld reduces computation through compact scene representations, short-horizon action-conditioned prediction, and selective candidate verification and score refinement. These designs support efficient future-informed planning without teacher distillation or additional domain-specific pre-training. On NAVSIMv1, FastWorld achieves 92.2 PDMS at 132 FPS on a single 4090 GPU. It also achieves 89.4 EPDMS on NAVSIMv2 and an average L2 of 0.40 over 3 seconds at 17 FPS on nuScenes. Code and models can be found at https://github.com/MoyangSensei/FastWorld.", "published": "2026-11-21", "comment": "23 pages total, 8 pages main text (4 figures, 8 tables), 12 pages supplementary material (9 figures, 5 tables)", "url": "https://arxiv.org/abs/2611.28779"}, {"id": "2611.25927", "title": "Fast-JEPA: Advancing the Success-Latency Frontier for Latent World Models", "authors": ["Yao Zhang", "Bin Yu", "Shijie Lian", "Haishan Liu", "Changti Wu", "Yu Wu", "Kai Chen"], "abstract": "Latent world models predict the outcomes of action sequences, but comparing candidate plans through recursive rollout remains expensive at test time. We introduce Fast-JEPA, a latent world model planning framework that advances the success-latency Pareto frontier of predictive search. Fast-JEPA reorganizes predictive computation to support effective action-sequence search at low planning cost. It constructs a goal-directed plan to guide search and directly predicts the outcomes of complete candidates for efficient comparison, avoiding recursive state rollout during refinement. Across PushT, Reacher, Cube, and TwoRoom, Fast-JEPA achieves 96.50% average success rate with 2.41x faster planning than INTACT. Search-budget sweeps show that its competitive success and low latency extend across candidate counts and refinement depths. We further introduce DynaGoal, a benchmark for evaluating world-model planning under dynamic out-of-distribution conditions, execution deadlines, and controlled response delays. Fast-JEPA achieves average success rates of 73.83% on DynaGoal-Shift and 87.67% on DynaGoal-Deadline, demonstrating the practical value of low-latency predictive planning under changing control conditions and execution-time constraints. Our project page is available at https://deepcybo-physai.github.io/Fast-JEPA.", "published": "2026-11-22", "comment": null, "url": "https://arxiv.org/abs/2611.25927"}, {"id": "2611.29609", "title": "JEPA-Shield: Safe Diffusion Planning with Latent World Models via Conformal Shielding", "authors": ["Taekyung Kim", "Ege Yuceel", "Steven Hong", "Georgios Fainekos", "Dimitra Panagou", "Bardh Hoxha"], "abstract": "Latent world models enable planning from images, but their predictions do not directly establish whether a robot will satisfy physical constraints. We present JEPA-Shield, which connects a frozen action-conditioned Joint-Embedding Predictive Architecture (JEPA) world model to task-space safety enforcement. Two downstream models predict relative motion from imagined latent rollouts and decode unsafe geometry from the current image. Split conformal prediction turns end-to-end motion-prediction errors into multi-horizon uncertainty tubes. A backup-based shield checks these tubes against physical constraints and screens both candidate trajectories and final proposals in diffusion-inspired sampling-based model predictive control. Under the stated exchangeability and initial-backup assumptions, we establish probabilistic constraint satisfaction at action-block boundaries for a returned plan executed without replanning. We also introduce VParkBench, with geometric car and tractor-trailer parking tasks and a editable photorealistic Gaussian-splatting environment. In closed-loop evaluation, JEPA-Shield achieves success rates of 84.4%, 82.3%, and 99.0%, respectively, with no observed constraint violations. Ablations show complementary benefits from shielding and uncertainty calibration. The results demonstrate the importance of grounding latent world-model predictions in task-space quantities and explicitly accounting for prediction uncertainty in safety-critical planning.", "published": "2026-11-22", "comment": "Project page: https://www.taekyung.me/jepa-shield", "url": "https://arxiv.org/abs/2611.29609"}, {"id": "2611.30530", "title": "Assembly-JEPA: Using World Models for Fine-Grained Industrial Image Verification", "authors": ["Michael Hollmer", "Andreas Fischer"], "abstract": "Automated verification of industrial assembly processes remains a challenging problem due to substantial visual variability, limited availability of labeled defect data, and the fine-grained nature of many assembly errors. Existing approaches often rely on object detection, CAD models, or supervised classification pipelines, which can struggle to generalize across changing products and assembly configurations. In this work, we propose a novel self-supervised assembly verification framework based on Joint Embedding Predictive Architectures (JEPAs). Starting from the JEPA-based world model LeWorldModel, we investigate how the architecture must be adapted to verify the correctness of fine-grained assembly operations. To this end, we formulate assembly verification as a predictive world modeling task operating on before-and-after observations of assembly processes. Experimental results on industrial assembly tasks demonstrate that the proposed approach reliably detects both fine-grained incorrect assembly states and action-state mismatches, achieving an AUROC of 86.9% on a newly introduced assembly verification dataset. These results indicate that JEPA-based predictive representations constitute a promising foundation for robust and data-efficient industrial assembly verification.", "published": "2026-11-23", "comment": null, "url": "https://arxiv.org/abs/2611.30530"}, {"id": "2605.23878", "title": "LaMo: Self-Supervised Latent Motion Priors for Physical Realism in Video Generation", "authors": ["Bo Jiang", "Depu Meng", "Yihan Hu", "Yichen Xie", "Tianshuo Xu", "Wei Zhan"], "abstract": "Modern video generators produce visually compelling clips but still struggle with physical and motion consistency, limiting their use as reliable world simulators. Existing remedies often rely on external simulators, teacher models, or curated physics-focused data. We explore a complementary self-supervised direction: extracting motion cues from the unlabeled videos already used to train video diffusion models. We propose LaMo, which formulates a latent motion prior over frame-to-frame latent changes conditioned on the current latent and prompt. This prior is exposed through two lightweight readouts: a macro motion drift used during training as a Motion Drift Loss, and a learned micro motion field used during sampling as Motion Prior Guidance. Both components are plug-and-play with existing video diffusion backbones, requiring no architectural or I/O changes. On VideoPhy, VideoPhy2, and PisaBench, LaMo improves CogVideoX backbones and outperforms recent physics-aware baselines that use external supervision. On VBench, it preserves overall generation quality while improving motion-related dimensions. These results suggest that unlabeled video contains useful motion supervision for improving physical fidelity in modern video diffusion models.", "published": "2026-11-22", "comment": "Project Page: https://lamo-ai.github.io/", "url": "https://arxiv.org/abs/2605.23878"}, {"id": "2611.30120", "title": "AxE: Benchmarking Agent-Environment Generalization of Video World Models via Grounded Events", "authors": ["Haiyu Xu", "Yiyang Chen", "Jiayi Zhou", "Jiaming Ji", "Juntao Dai", "Yaodong Yang", "Boyuan Chen"], "abstract": "Edge cases are not the long tail; they are the norm. An embodied system deployed across changing environments, bodies, objects, and tasks will routinely encounter combinations that were absent from its training data. General-purpose physical intelligence therefore requires world models that reuse prior knowledge, predict consequences, and adapt with little or no additional training. Yet current evaluations of conditional video generation emphasize visual quality, prompt alignment, or isolated physical plausibility, leaving systematic generalization difficult to measure. We introduce AxE Bench, a benchmark that organizes condition changes along eight factors of the acting agent and of its environment, and pairs every original condition with controlled variants that change one side or both. WBench-plus applies the same structure to an existing multi-turn benchmark, pairing each WBench scenario with variants on the environment side, through its world setting or camera behavior, or on the agent side, through its interaction instructions. Additionally, to score generated futures, we develop an evaluation harness that combines vision-language reasoning with targeted computer-vision evidence, converting each video into temporally localized events and comparing generated events with reference events in both time and semantics. We summarize each model with the AxE Score, event Fidelity weighted by its Stability across original-variant pairs. Across twenty models, generated events match reference events far more often in timing than in content: no model exceeds a Fidelity of 13.01, the highest Stability is 0.55, and the highest AxE Score is 7.10. Together, these components turn world-model generalization from an informal aspiration into a falsifiable evaluation program for real and simulated interactions. Our project website can be found at: AxEBench.github.io", "published": "2026-11-23", "comment": "Project page: https://AxEBench.github.io", "url": "https://arxiv.org/abs/2611.30120"}, {"id": "2611.30597", "title": "ViDiHand2: Unifying Video Diffusion Priors and Hand Geometry for 3D Hand Motion Reconstruction in the Wild", "authors": ["Yuxi Wang", "Yufei Liu", "Chengkai Jin", "Qingyue Chen", "Wenqi Ouyang", "Tianyi Wei", "Kerui Ren", "Siyuan Huang", "Zhiqi Shen", "Hongsheng Li", "Xingang Pan"], "abstract": "Learning robot manipulation from egocentric human videos requires accurate metric 3D hand motion. Recent methods leverage pretrained video diffusion model (VDM) priors to recover occluded hands directly from full-frame videos, but their appearance-based depth regression generalizes poorly to unseen cameras. In this work, we propose ViDiHand2, a geometry-driven framework that reformulates VDM-based hand depth estimation from direct regression into fine-grained geometric constraint solving. Specifically, we introduce Fine-Grained Geometric Lifting and Clip-Level Ray Fitting, which recover metric depth by enforcing geometric consistency between pixel-aligned 2D joints and the metric structure of MANO hands, while leveraging temporal observations across the clip. Since the lifting relies on these 2D joints, to improve robustness under occlusion and image truncation, we further develop Confidence-Gated Fusion to adaptively combine geometrically lifted joints with MANO predictions according to localization confidence. Finally, we enhance the VDM backbone to better capture spatial-temporal representations and produce the per-frame 2D joint and MANO predictions that both steps rely on. Extensive experiments on seven public datasets demonstrate that ViDiHand2 consistently outperforms 18 baselines, reducing in-the-wild absolute joint error by 42% and detection failures by 8.82x compared with the best baseline on each metric, while running at 57 FPS. The code is available at https://github.com/NTUYWANG103/ViDiHand.", "published": "2026-11-23", "comment": "Main text 8 pages with supplementary material, 54 pages in total", "url": "https://arxiv.org/abs/2611.30597"}, {"id": "2611.30836", "title": "Can Multimodal Fusion MakeSense for Embodied Vision in Degraded Sensing?", "authors": ["Cheng-Ru Chou", "Shih-Yu Lai", "Pei-Lin Chiang", "Shou-Po Tsai", "Jing-Zhe Huang", "Fukuharu Tanaka", "Hirozumi Yamaguchi", "Bing-Yu Chen", "Yu-Lun Liu", "Hsun-Ping Hsieh"], "abstract": "Embodied vision systems rely on complementary sensors to perceive and act as conditions change. Even models that accept arbitrary sensor subsets can exhibit negative fusion: adding a sensor increases prediction error. We propose MakeSense, a multimodal fusion framework that preserves sensor-specific evidence in private streams and combines information through shared bottleneck tokens. Training pairs full and subset views of the same degraded observations, penalizing higher error with more sensors. Where geometry permits, the distance readout uses range measurements alone, while the rest of the prediction draws on all available inputs. Paired tests across five datasets reveal helpful and harmful sensor additions. MakeSense reduces negative fusion on MM-Fi. With lightweight adapters and per-dataset training, the same design improves UAV localization on MMAUD, cooperative 3D detection on V2X-Real, few-shot pose transfer to RELI11D, and command prediction on Humanoid-Everyday, where a world model trained on the frozen core's outputs forecasts future fused states more accurately than a linear baseline at longer tested horizons. MakeSense supports embodied sensing across human activity, aerial systems, robotics, and autonomous driving.", "published": "2026-11-23", "comment": null, "url": "https://arxiv.org/abs/2611.30836"}, {"id": "2611.24731", "title": "HandWorldBench: A Unified Benchmark for Hand-Centric World Models", "authors": ["Zhaolu Wang", "Jiacheng Xu", "Lihong Wang", "Shuqing Wang", "Jianjie Fang", "Ziyou Wang", "Xvyuan Liu", "Rongze Tang", "Yiding Ma", "Xin Zhang", "Jiawei Chen", "Wei Wu", "Chen Gao", "Yong Li", "Zhibo Chen"], "abstract": "Recent advances in world models are opening new possibilities for fine-grained embodied tasks, with hand-object interaction offering a particularly demanding setting. Modeling these interactions involves capturing how hand actions change objects and how the resulting states persist over time. Yet systematic evaluation tailored to these hand-centric capabilities remains underdeveloped. To address this gap, we introduce HandWorldBench, a unified benchmark that systematically evaluates hand-centric world models across human hands, simulated dexterous hands, and real dexterous hands along six dimensions: visual quality, hand fidelity, appearance consistency, instruction following, physical consistency, and temporal coherence. To construct the benchmark, we develop a data curation pipeline that extracts hand-object interaction clips and screens them for quality, yielding 20,500 high-quality egocentric clips from over 600 hours of footage. We then manually select 500 clips covering seven task families for evaluation. Benchmarking eleven models under a unified protocol reveals that stronger hand-pose control does not consistently translate into coherent object-state evolution and persistence or robust cross-embodiment performance, with several specialized hand-control models underperforming general-purpose text/image-to-video generators on dexterous-hand tasks.", "published": "2026-11-21", "comment": null, "url": "https://arxiv.org/abs/2611.24731"}]}}};
